use std::collections::HashMap;
use std::net::{IpAddr, ToSocketAddrs};
use std::sync::{Arc, RwLock};
use std::time::{Duration, Instant};

#[derive(Clone, Debug, PartialEq)]
enum Role {
    Admin,
    Worker,
    ReadOnly,
}

#[derive(Clone, Debug)]
struct ServiceEndpoint {
    hostname: String,
    resolved_ip: IpAddr,
    resolved_at: Instant,
    role: Role,
}

struct DnsCache {
    entries: HashMap<String, (IpAddr, Instant)>,
    ttl: Duration,
}

impl DnsCache {
    fn new(ttl: Duration) -> Self {
        Self {
            entries: HashMap::new(),
            ttl,
        }
    }

    fn resolve(&mut self, hostname: &str) -> Result<IpAddr, String> {
        if let Some((ip, resolved_at)) = self.entries.get(hostname) {
            if resolved_at.elapsed() < self.ttl {
                return Ok(*ip);
            }
        }
        let addr = format!("{}:0", hostname)
            .to_socket_addrs()
            .map_err(|e| format!("DNS resolution failed: {}", e))?
            .next()
            .ok_or_else(|| "No addresses found".to_string())?;
        let ip = addr.ip();
        self.entries.insert(hostname.to_string(), (ip, Instant::now()));
        Ok(ip)
    }
}

fn is_internal_network(ip: IpAddr) -> bool {
    match ip {
        IpAddr::V4(v4) => {
            v4.is_private() || v4.is_loopback() || v4.is_link_local()
        }
        IpAddr::V6(v6) => v6.is_loopback(),
    }
}

struct MessageQueueConsumer {
    dns_cache: Arc<RwLock<DnsCache>>,
    allowed_endpoints: Vec<ServiceEndpoint>,
    acl: HashMap<String, Role>,
}

impl MessageQueueConsumer {
    fn new() -> Self {
        Self {
            dns_cache: Arc::new(RwLock::new(DnsCache::new(Duration::from_secs(300)))),
            allowed_endpoints: Vec::new(),
            acl: HashMap::new(),
        }
    }

    fn register_endpoint(&mut self, hostname: &str, role: Role) -> Result<(), String> {
        let mut cache = self.dns_cache.write().unwrap();
        let ip = cache.resolve(hostname)?;

        // Security check: only allow external endpoints for non-admin roles
        if role == Role::Admin && !is_internal_network(ip) {
            return Err("Admin endpoints must be on internal network".to_string());
        }

        self.allowed_endpoints.push(ServiceEndpoint {
            hostname: hostname.to_string(),
            resolved_ip: ip,
            role: role.clone(),
            resolved_at: Instant::now(),
        });
        self.acl.insert(hostname.to_string(), role);
        Ok(())
    }

    fn process_message(&self, target_hostname: &str, payload: &[u8]) -> Result<Vec<u8>, String> {
        let endpoint = self.allowed_endpoints.iter()
            .find(|e| e.hostname == target_hostname)
            .ok_or_else(|| "Endpoint not registered".to_string())?;

        let role = self.acl.get(target_hostname)
            .ok_or_else(|| "No ACL entry".to_string())?;

        // Re-resolve DNS for the actual connection to handle IP changes
        let current_ip = {
            let mut cache = self.dns_cache.write().unwrap();
            cache.resolve(target_hostname)?
        };

        // Verify the endpoint still matches our security policy
        // SECURE: checks against current_ip that will actually be used
        if *role == Role::Admin && !is_internal_network(current_ip) {
            return Err("Security violation: admin endpoint on external network".to_string());
        }

        // Use current_ip for actual connection (validated above)
        self.send_to_endpoint(current_ip, *role == Role::Admin, payload)
    }

    fn send_to_endpoint(&self, ip: IpAddr, is_admin: bool, payload: &[u8]) -> Result<Vec<u8>, String> {
        if is_admin {
            // Admin messages include internal service tokens
            let mut enriched = b"ADMIN_TOKEN:secret_internal_key|".to_vec();
            enriched.extend_from_slice(payload);
            // In real code: connect to ip and send enriched payload
            Ok(enriched)
        } else {
            Ok(payload.to_vec())
        }
    }
}

fn main() {
    let mut consumer = MessageQueueConsumer::new();

    // Register an internal admin endpoint
    consumer.register_endpoint("internal-service.corp.local", Role::Admin).unwrap();
    consumer.register_endpoint("external-worker.example.com", Role::Worker).unwrap();

    // Process messages
    let result = consumer.process_message("internal-service.corp.local", b"get_secrets");
    println!("Result: {:?}", result);
}
